"""
    Return a mapping with the type as key, and the index number.
    :param types: a dictionary of types with the type name, and the message type
    :type types: dict
    :return: message mapping
    :rtype: dict
    """
def _get_message_mapping(types: dict) -> dict {
    message_mapping = {};
    entry_index = 2;
    for (_type, message) in types.items() {
        message_mapping[_type] = entry_index;
        entry_index += 1;
    }
    return message_mapping;
}

"""
   The assumption is that the symbolic algebra optimization will always break
   out the function evaluation. Therefore there always is a line where the
   functional value is assigned to a variable. The actual functional
   subroutine call, at the latest, has to happen on the line before.
   This routine returns the line where the variable first appears.
   """
def find_subroutine_call_insertion_point(
    lines: Any, ifbranch: Any, varname: Any
) -> object {
    (lineno_start, lineno_end) = ifbranch;
    line = lineno_start;
    insert_point = -1;
    while (line <= lineno_end) {
        aline = lines[line];
        aline = aline.split(" = ");
        key = aline[0].lstrip();
        if (key == varname) {
            insert_point = line;
            break;
        }
        line += 1;
    }
    return insert_point;
}
